from fastapi import FastAPI, Depends, Security
from fastapi.security import HTTPBearer, HTTPAuthorizationCredentials
from fastapi.openapi.utils import get_openapi

def get_token_header(token: str = Security(HTTPBearer(), auto_error=False)):
    return token

app = FastAPI(dependencies=[Depends(get_token_header)])

@app.get("/")
def read_root():
    return {"Hello": "World"}

if __name__ == "__main__":
    openapi_schema = app.openapi()
    security_schemes = openapi_schema.get("components", {}).get("securitySchemes", {})
    print(f"Security Schemes: {security_schemes}")
    if not security_schemes:
        print("FAILED: No security schemes found in OpenAPI schema")
        exit(1)
    else:
        print("SUCCESS: Security schemes found")
        exit(0)
